profile = {-100: 4, -80: 8, -60: 13, -40: 23, -20: 34, 0: 36, 20: 32, 40: 24, 60: 12, 80: 8, 100: 0}
xs = sorted(profile.keys())
ys = [profile[x] for x in xs]

def interp(d):
    if d <= xs[0] or d >= xs[-1]:
        return 0.0
    for i in range(len(xs)-1):
        if xs[i] <= d <= xs[i+1]:
            t = (d - xs[i]) / (xs[i+1] - xs[i])
            return ys[i] + t * (ys[i+1] - ys[i])
    return 0.0

for pitch in [40, 45, 50, 55, 60]:
    vals = []
    for y in range(0, pitch+1, 5):
        tot = sum(interp(y - k*pitch) for k in range(-10, 11))
        vals.append(tot)
    print(f"pitch={pitch}: min={min(vals):.1f}, max={max(vals):.1f}, mean={sum(vals)/len(vals):.1f}")
'

